// Process new task
const input = $input.first().json;

const task = {
  id: input.id || `TASK-${Date.now()}`,
  title: input.title || input.name || 'Untitled Task',
  description: input.description || '',
  project: input.project || input.projectId || '',
  projectName: input.projectName || '',

  // Assignment
  assignee: input.assignee || null,
  reporter: input.reporter || input.createdBy || '',

  // Timing
  createdAt: new Date().toISOString(),
  dueDate: input.dueDate || null,
  startDate: input.startDate || null,

  // Status
  status: input.status || 'backlog',
  priority: input.priority || 'medium',
  type: input.type || 'task', // task, bug, feature, epic

  // Effort
  estimatedHours: input.estimatedHours || null,
  loggedHours: 0,

  // Dependencies
  blockedBy: input.blockedBy || [],
  blocking: input.blocking || [],

  // Labels
  labels: input.labels || [],
  sprint: input.sprint || null,
  epic: input.epic || null
};

return {
  json: task
};

