// Auto-assign task based on skills and availability
const data = $input.first().json;

// In production, this would query team availability
const teamMembers = JSON.parse($env.TEAM_MEMBERS || '[]');
const requiredSkills = data.requiredSkills || [];

// Simple matching - find first available member with required skills
let assignee = data.assignee;
if (!assignee && teamMembers.length > 0) {
  const match = teamMembers.find(m => 
    requiredSkills.some(skill => m.skills?.includes(skill))
  );
  assignee = match?.name || teamMembers[0]?.name || 'unassigned';
}

return {
  json: {
    ...data,
    assignee: assignee,
    assignedAt: new Date().toISOString(),
    status: 'todo'
  }
};

// Check for overdue tasks
const tasks = $input.first().json.tasks || $input.first().json || [];
const now = new Date();

const taskList = Array.isArray(tasks) ? tasks : [tasks];

const categorized = {
  overdue: taskList.filter(t => t.dueDate && new Date(t.dueDate) < now),
  dueToday: taskList.filter(t => {
    if (!t.dueDate) return false;
    const due = new Date(t.dueDate);
    return due.toDateString() === now.toDateString();
  }),
  inProgress: taskList.filter(t => t.status === 'in_progress'),
  blocked: taskList.filter(t => t.status === 'blocked'),
  inReview: taskList.filter(t => t.status === 'review')
};

return {
  json: {
    ...categorized,
    totalActive: taskList.length,
    date: now.toISOString()
  }
};

