// Calculate sprint metrics
const sprint = $input.first().json;
const tasks = sprint.tasks || [];

const metrics = {
  sprintName: sprint.name || 'Current Sprint',
  startDate: sprint.startDate,
  endDate: sprint.endDate,

  // Task counts
  totalTasks: tasks.length,
  completed: tasks.filter(t => t.status === 'done').length,
  inProgress: tasks.filter(t => t.status === 'in_progress').length,
  todo: tasks.filter(t => t.status === 'todo').length,
  blocked: tasks.filter(t => t.status === 'blocked').length,

  // Points
  totalPoints: tasks.reduce((sum, t) => sum + (t.points || 0), 0),
  completedPoints: tasks.filter(t => t.status === 'done').reduce((sum, t) => sum + (t.points || 0), 0),

  // Hours
  estimatedHours: tasks.reduce((sum, t) => sum + (t.estimatedHours || 0), 0),
  loggedHours: tasks.reduce((sum, t) => sum + (t.loggedHours || 0), 0),

  // Velocity
  completionRate: tasks.length > 0 ? ((tasks.filter(t => t.status === 'done').length / tasks.length) * 100).toFixed(1) : 0,

  // By assignee
  byAssignee: tasks.reduce((acc, t) => {
    const assignee = t.assignee || 'Unassigned';
    if (!acc[assignee]) acc[assignee] = { completed: 0, total: 0 };
    acc[assignee].total++;
    if (t.status === 'done') acc[assignee].completed++;
    return acc;
  }, {})
};

return {
  json: metrics
};

